/**
 * Compiles tokens/tokens.json (the Tandrix design system's token file) into
 *   src/generated/tokens.ts  — typed, alias-resolved values for React Native and TS consumers
 *   src/generated/tokens.css — CSS custom properties per theme for web and Electron
 * Run with --check to fail when the generated files are out of date (CI).
 */
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const SRC = join(root, "tokens/tokens.json");
const OUT_TS = join(root, "src/generated/tokens.ts");
const OUT_CSS = join(root, "src/generated/tokens.css");

type Themed = string | Record<string, string>;
interface Token {
  name: string;
  value: Themed;
  usage?: string;
}
interface TextStyle {
  name: string;
  fontSize: string;
  lineHeight: string;
  fontWeight: number;
  letterSpacing?: string;
  family?: string;
  usage?: string;
}
interface TokenFile {
  name: string;
  color: { themes: { id: string; name: string }[]; tokens: Token[] };
  type: {
    families: Record<string, string>;
    groups: { name: string; family: string; styles: TextStyle[] }[];
  };
  spacing: { tokens: Token[] };
  radius: { tokens: Token[] };
  size: { tokens: Token[] };
  shadow: { tokens: Token[] };
}

export function compile(json: TokenFile): { ts: string; css: string } {
  const themes = json.color.themes.map((t) => t.id);
  const first = themes[0]!;
  const colorByName = new Map(json.color.tokens.map((t) => [t.name, t.value]));

  const raw = (v: Themed, theme: string): string =>
    typeof v === "string" ? v : (v[theme] ?? v[first]!);
  const alias = (s: string): string | null => /^\{(.+)\}$/.exec(s)?.[1] ?? null;

  const resolve = (name: string, theme: string, depth = 0): string => {
    if (depth > 16) throw new Error(`Alias chain too deep at ${name}`);
    const v = colorByName.get(name);
    if (v === undefined) throw new Error(`Unknown colour token ${name}`);
    const r = raw(v, theme);
    const a = alias(r);
    return a ? resolve(a, theme, depth + 1) : r;
  };

  const px = (s: string): number => {
    const m = /^(-?\d+(?:\.\d+)?)px$/.exec(s);
    if (!m) throw new Error(`Expected px value, got ${s}`);
    return Number(m[1]);
  };

  // ---- TS ----
  const colorNames = json.color.tokens.map((t) => t.name);
  const colors: Record<string, Record<string, string>> = {};
  const shadows: Record<string, Record<string, string>> = {};
  for (const th of themes) {
    colors[th] = Object.fromEntries(colorNames.map((n) => [n, resolve(n, th)]));
    shadows[th] = Object.fromEntries(json.shadow.tokens.map((t) => [t.name, raw(t.value, th)]));
  }
  const nums = (fam: { tokens: Token[] }) =>
    Object.fromEntries(fam.tokens.map((t) => [t.name, px(raw(t.value, first))]));

  const textStyles: Record<string, unknown> = {};
  for (const g of json.type.groups) {
    for (const s of g.styles) {
      textStyles[s.name] = {
        family: s.family ?? g.family,
        fontSize: px(s.fontSize),
        lineHeight: px(s.lineHeight),
        fontWeight: s.fontWeight,
        letterSpacing: s.letterSpacing ? px(s.letterSpacing) : 0,
      };
    }
  }

  const j = (v: unknown) => JSON.stringify(v, null, 2);
  const ts = `// Generated by scripts/build-tokens.ts from tokens/tokens.json. Do not edit.
export const themeNames = ${j(themes)} as const;
export type ThemeName = (typeof themeNames)[number];

export const colorTokenNames = ${j(colorNames)} as const;
export type ColorToken = (typeof colorTokenNames)[number];

export const colors: Record<ThemeName, Record<ColorToken, string>> = ${j(colors)};

export const shadows: Record<ThemeName, Record<${json.shadow.tokens.map((t) => j(t.name)).join(" | ")}, string>> = ${j(shadows)};

export const space = ${j(nums(json.spacing))} as const;
export type SpaceToken = keyof typeof space;

export const radius = ${j(nums(json.radius))} as const;
export type RadiusToken = keyof typeof radius;

export const size = ${j(nums(json.size))} as const;
export type SizeToken = keyof typeof size;

export const fontFamilies = ${j(json.type.families)} as const;
export type FontFamily = keyof typeof fontFamilies;

export interface TextStyleSpec {
  family: FontFamily;
  fontSize: number;
  lineHeight: number;
  fontWeight: 400 | 500 | 600 | 700;
  letterSpacing: number;
}

export const textStyles = ${j(textStyles)} as const satisfies Record<string, TextStyleSpec>;
export type TextStyleName = keyof typeof textStyles;
`;

  // ---- CSS (same layout as the design system's tokens.css) ----
  const cssVal = (v: Themed, th: string) => {
    const r = raw(v, th);
    const a = alias(r);
    return a ? `var(--${a})` : r;
  };
  const block = (sel: string, lines: string[]) => `${sel} {\n${lines.join("\n")}\n}`;
  const out: string[] = [`/* ${json.name} — generated from tokens.json */`];
  const themed = [...json.color.tokens, ...json.shadow.tokens];
  out.push(
    block(
      `:root, [data-theme="${first}"]`,
      themed.map((t) => `  --${t.name}: ${cssVal(t.value, first)};`),
    ),
  );
  for (const th of themes.slice(1)) {
    out.push(
      block(
        `[data-theme="${th}"]`,
        themed
          .filter(
            (t) =>
              (typeof t.value !== "string" && th in t.value) ||
              (typeof t.value === "string" && alias(t.value)),
          )
          .map((t) => `  --${t.name}: ${cssVal(t.value, th)};`),
      ),
    );
  }
  out.push(
    block(":root", [
      ...[...json.spacing.tokens, ...json.radius.tokens, ...json.size.tokens].map(
        (t) => `  --${t.name}: ${raw(t.value, first)};`,
      ),
      ...Object.entries(json.type.families).map(([k, v]) => `  --font-${k}: ${v};`),
    ]),
  );
  for (const g of json.type.groups) {
    for (const s of g.styles) {
      const d = [
        `font-family: var(--font-${s.family ?? g.family})`,
        `font-size: ${s.fontSize}`,
        `line-height: ${s.lineHeight}`,
        `font-weight: ${s.fontWeight}`,
      ];
      if (s.letterSpacing) d.push(`letter-spacing: ${s.letterSpacing}`);
      out.push(`.${s.name} { ${d.join("; ")}; }`);
    }
  }
  return { ts, css: out.join("\n") + "\n" };
}

function main() {
  const json = JSON.parse(readFileSync(SRC, "utf8")) as TokenFile;
  const { ts, css } = compile(json);
  if (process.argv.includes("--check")) {
    const stale = [
      [OUT_TS, ts],
      [OUT_CSS, css],
    ].filter(([p, c]) => !existsSync(p!) || readFileSync(p!, "utf8") !== c);
    if (stale.length) {
      console.error(
        `Generated tokens are out of date: ${stale.map(([p]) => p).join(", ")}. Run pnpm --filter @tandrix/ui build.`,
      );
      process.exit(1);
    }
    console.log("Generated tokens are up to date.");
    return;
  }
  writeFileSync(OUT_TS, ts);
  writeFileSync(OUT_CSS, css);
  console.log(`Wrote ${OUT_TS} and ${OUT_CSS}`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) main();
